sp_CriarContaReceber	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_CriarContaReceber`(\n\n    IN p_idEmpresa     INT,\n\n    IN p_cliente_id    INT,\n\n    IN p_pedido_id     INT,\n\n    IN p_lancamento_id INT,\n\n    IN p_descricao     VARCHAR(300),\n\n    IN p_valorTotal    DECIMAL(10,2),\n\n    IN p_dthVencimento DATE\n\n)\nBEGIN\n\n    INSERT INTO ContaReceber (\n\n        idEmpresa, cliente_id, pedido_id, lancamento_id,\n\n        descricao, valorTotal, dthVencimento, status\n\n    ) VALUES (\n\n        p_idEmpresa, p_cliente_id, p_pedido_id, p_lancamento_id,\n\n        p_descricao, p_valorTotal, p_dthVencimento, 'ABERTO'\n\n    );\n\n\n\n    \n\n    UPDATE Cliente\n\n    SET saldoDevedor = saldoDevedor + p_valorTotal\n\n    WHERE idCliente = p_cliente_id;\n\n\n\n    SELECT LAST_INSERT_ID() AS idContaReceber;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
